               <form onSubmit={handleSubmit}>
                 <ConsentField
                   checked={agreed}
                   onChange={(event) => setAgreed(event.target.checked)}
                 />
                 <SubmitButton />
                 {submitted && (
                   <p className="status">Thanks — your consent has been recorded.</p>
                 )}
               </form>
             </section>
           </main>
         );
       }

